const memData = $json;
const usedMemory = parseInt(memData.used_memory || '0', 10);
const usedMemoryPeak = parseInt(memData.used_memory_peak || '0', 10);
const usedMemoryHuman = memData.used_memory_human || '0M';
const peakHuman = memData.used_memory_peak_human || '0M';

// 500MB üzeri bellek kullanımı uyarı eşiğidir
const isMemoryHigh = usedMemory > (500 * 1024 * 1024);
const fragmentationRatio = parseFloat(memData.mem_fragmentation_ratio || '1.0');
const isFragHigh = fragmentationRatio > 2.5;

const alertRequired = isMemoryHigh || isFragHigh;

return [{
  json: {
    timestamp: new Date().toISOString(),
    usedMemoryHuman,
    peakHuman,
    fragmentationRatio,
    alertRequired,
    status: alertRequired ? 'WARNING' : 'HEALTHY',
    summary: `Redis RAM: ${usedMemoryHuman} (Zirve: ${peakHuman}) | Parçalanma: ${fragmentationRatio}`
  }
}];

